-- 02-load-data
-- GENERATED by scripts/generate_install_sql.py from data/ and sql/. Do not edit by hand.
-- Run from the repo root: snow sql -c <connection> --enable-templating NONE -f install/02-load-data.sql

-- Order: (a) upload parquet, (b) base tables, (c) COPY INTO, (d) functions, procedures,
-- views and dynamic tables in dependency order. Table DDL is CREATE OR REPLACE.

-- (a) Upload parquet files
PUT 'file://data/GAME_CATALOG/*.parquet' @ONTOLOGY_DEMO.PUBLIC.DATA_STAGE/GAME_CATALOG/ AUTO_COMPRESS = FALSE OVERWRITE = TRUE PARALLEL = 8;
PUT 'file://data/GAME_SALES/*.parquet' @ONTOLOGY_DEMO.PUBLIC.DATA_STAGE/GAME_SALES/ AUTO_COMPRESS = FALSE OVERWRITE = TRUE PARALLEL = 8;

-- (b) Base tables
