	STATUS VARCHAR(1),
	primary key (CUSTOMER_ID)
)COMMENT='Platform network accounts (PSN-style) that buy hardware, buy digital products, and hold subscriptions. PLATFORM_ID is the account home network.'
;

-- GAME_SALES.DIGITAL_PRODUCTS
create or replace TABLE ONTOLOGY_DEMO.GAME_SALES.DIGITAL_PRODUCTS (
	DIGITAL_PRODUCT_ID NUMBER(38,0) NOT NULL autoincrement start 1 increment 1 noorder,
	TITLE_ID NUMBER(38,0),
	CATEGORY_ID NUMBER(38,0) NOT NULL,
	PRODUCT_NAME VARCHAR(16777216) NOT NULL,
	LIST_PRICE FLOAT,
	CURRENCY_CODE VARCHAR(3) DEFAULT 'USD',
	IS_CONSUMABLE BOOLEAN DEFAULT FALSE,
	RELEASE_DATE DATE,
	SKU_CODE VARCHAR(16777216),
	STATUS VARCHAR(16777216),
	primary key (DIGITAL_PRODUCT_ID)
)COMMENT='Unified SKU catalog for every digital good: base games, DLC, expansions, season and battle passes, cosmetics, consumables, loot boxes, and virtual currency bundles. GAME_ID is null for platform-wide items.'
;

-- GAME_SALES.DIGITAL_PRODUCT_TRANSACTIONS
create or replace TABLE ONTOLOGY_DEMO.GAME_SALES.DIGITAL_PRODUCT_TRANSACTIONS (
	TRANSACTION_ID NUMBER(38,0) NOT NULL autoincrement start 1 increment 1 noorder,
	DIGITAL_PRODUCT_ID NUMBER(38,0) NOT NULL,
	TITLE_ID NUMBER(38,0),
	PLAYER_ID NUMBER(38,0),
	TRANSACTION_TIMESTAMP TIMESTAMP_NTZ(9) NOT NULL,
	QUANTITY NUMBER(38,0) DEFAULT 1,
	UNIT_PRICE FLOAT,
	GROSS_REVENUE FLOAT,
	PLATFORM_COMMISSION_PCT FLOAT,
	NET_DEVELOPER_REVENUE FLOAT,
	PLATFORM_ID NUMBER(38,0) COMMENT 'Platform version / store the purchase was for (FK GAME_SALES.PLATFORMS). Drives store commission: PlayStation platforms 0%, other stores 30%.',
	primary key (TRANSACTION_ID)
)COMMENT='Digital purchase transactions for every DIGITAL_PRODUCTS category. GAME_ID is denormalized from DIGITAL_PRODUCTS. GROSS_REVENUE minus NET_DEVELOPER_REVENUE is the platform commission.'
;

-- GAME_SALES.MONETIZATION_TYPES
create or replace TABLE ONTOLOGY_DEMO.GAME_SALES.MONETIZATION_TYPES (
	MONETIZATION_ID NUMBER(38,0) NOT NULL,
	MONETIZATION_NAME VARCHAR(16777216) NOT NULL,
	unique (MONETIZATION_NAME),
	primary key (MONETIZATION_ID)
)COMMENT='Sales system copy of monetization model names (premium, dlc, microtransactions, ...) used to pick each game''s synthetic sales profile. Loaded from data/GAME_SALES (no sync process).'
;

-- GAME_SALES.GAME_MONETIZATION
create or replace TABLE ONTOLOGY_DEMO.GAME_SALES.GAME_MONETIZATION (
	TITLE_ID NUMBER(38,0) NOT NULL,
	MONETIZATION_ID NUMBER(38,0) NOT NULL,
	primary key (TITLE_ID, MONETIZATION_ID),
	foreign key (MONETIZATION_ID) references ONTOLOGY_DEMO.GAME_SALES.MONETIZATION_TYPES(MONETIZATION_ID)
)COMMENT='Sales system copy: monetization models each game uses. Loaded from data/GAME_SALES (no sync process).'
;

-- GAME_SALES.GAME_PLATFORMS
create or replace TABLE ONTOLOGY_DEMO.GAME_SALES.GAME_PLATFORMS (
	GAME_PLATFORM_ID NUMBER(38,0) NOT NULL,
	TITLE_ID NUMBER(38,0),
	PLATFORM_ID NUMBER(38,0),
	EXCLUSIVITY_TYPE VARCHAR(16777216),
	EXCLUSIVE_START DATE,
	EXCLUSIVE_END DATE,
	EXCLUSIVITY_NOTE VARCHAR(16777216),
	IS_EXCLUSIVE VARCHAR(1),
	primary key (GAME_PLATFORM_ID)
)COMMENT='Sales system copy: which platforms each game is sold on, with exclusivity windows (drives store availability dates and VW_PLATFORM_EXCLUSIVITY). Same GAME_PLATFORM_IDs as GAME_CATALOG. Loaded from data/GAME_SALES (no sync process).'
;

-- GAME_SALES.HARDWARE_PRODUCTS
create or replace TABLE ONTOLOGY_DEMO.GAME_SALES.HARDWARE_PRODUCTS (
	HARDWARE_PRODUCT_ID NUMBER(38,0) NOT NULL autoincrement start 1 increment 1 noorder,
	PRODUCT_NAME VARCHAR(16777216) NOT NULL,
	PRODUCT_TYPE VARCHAR(16777216) NOT NULL,
	PLATFORM_ID NUMBER(38,0),
	MANUFACTURER VARCHAR(16777216),
	LIST_PRICE FLOAT,
	RELEASE_DATE DATE,
	primary key (HARDWARE_PRODUCT_ID)
)COMMENT='Catalog of consoles, controllers, VR headsets, and accessories. PRODUCT_TYPE is CONSOLE, CONTROLLER, VR_HEADSET, or ACCESSORY. PLATFORM_ID is null for cross-platform accessories.'
;

-- GAME_SALES.HARDWARE_SALES_TRANSACTIONS
create or replace TABLE ONTOLOGY_DEMO.GAME_SALES.HARDWARE_SALES_TRANSACTIONS (
	TRANSACTION_ID NUMBER(38,0) NOT NULL autoincrement start 1 increment 1 noorder,
	HARDWARE_PRODUCT_ID NUMBER(38,0) NOT NULL,
	BUYER_ID NUMBER(38,0),
	SALE_TIMESTAMP TIMESTAMP_NTZ(9) NOT NULL,
	REGION VARCHAR(16777216),
	QUANTITY NUMBER(38,0) DEFAULT 1,
	UNIT_PRICE FLOAT,
	GROSS_REVENUE FLOAT,
	primary key (TRANSACTION_ID),
	foreign key (HARDWARE_PRODUCT_ID) references ONTOLOGY_DEMO.GAME_SALES.HARDWARE_PRODUCTS(HARDWARE_PRODUCT_ID)
)COMMENT='Hardware sale transactions (consoles and peripherals). ACCOUNT_ID is null for anonymous retail purchases. Not attributable to a single game.'
;

-- GAME_SALES.PLATFORMS
create or replace TABLE ONTOLOGY_DEMO.GAME_SALES.PLATFORMS (
	PLATFORM_ID NUMBER(38,0) NOT NULL,
	PLATFORM_NAME VARCHAR(16777216),
	PLATFORM_CODE VARCHAR(16777216),
	primary key (PLATFORM_ID)
)COMMENT='Sales system copy of platforms (consoles, PC, mobile) that hardware and digital sales are recorded against. Loaded from data/GAME_SALES (no sync process).'
;

-- GAME_SALES.REVENUE_TYPES
create or replace TABLE ONTOLOGY_DEMO.GAME_SALES.REVENUE_TYPES (
	CATEGORY_ID NUMBER(38,0) NOT NULL autoincrement start 1 increment 1 noorder,
	MONETIZATION_TYPE VARCHAR(16777216) NOT NULL,
	CATEGORY_GROUP VARCHAR(16777216) NOT NULL,
	DESCRIPTION VARCHAR(16777216),
	unique (MONETIZATION_TYPE),
	primary key (CATEGORY_ID)
)COMMENT='Commerce taxonomy for every way the platform earns revenue. CATEGORY_GROUP rolls categories up to HARDWARE, DIGITAL, or SUBSCRIPTION.'
;

-- GAME_SALES.SUBSCRIPTION_PLANS
create or replace TABLE ONTOLOGY_DEMO.GAME_SALES.SUBSCRIPTION_PLANS (
	PLAN_ID NUMBER(38,0) NOT NULL autoincrement start 1 increment 1 noorder,
	PLAN_NAME VARCHAR(16777216) NOT NULL,
	PLAN_TIER VARCHAR(16777216),
	GAME_ID NUMBER(38,0),
	BILLING_CYCLE VARCHAR(16777216),
	LIST_PRICE FLOAT,
	CURRENCY_CODE VARCHAR(3) DEFAULT 'USD',
	primary key (PLAN_ID)
)COMMENT='Subscription plan catalog. GAME_ID null means a platform-wide plan (e.g. PS Plus Essential/Extra/Premium); non-null means a single game subscription. BILLING_CYCLE is MONTHLY, QUARTERLY, or ANNUAL.'
;

-- GAME_SALES.SUBSCRIPTION_CHARGES
create or replace TABLE ONTOLOGY_DEMO.GAME_SALES.SUBSCRIPTION_CHARGES (
	CHARGE_ID NUMBER(38,0) NOT NULL autoincrement start 1 increment 1 noorder,
	PLAN_ID NUMBER(38,0) NOT NULL,
	SUBSCRIBER_ID NUMBER(38,0) NOT NULL,
	CHARGE_TIMESTAMP TIMESTAMP_NTZ(9) NOT NULL,
	BILLING_PERIOD_START DATE,
	BILLING_PERIOD_END DATE,
	GROSS_REVENUE FLOAT,
	primary key (CHARGE_ID),
	foreign key (PLAN_ID) references ONTOLOGY_DEMO.GAME_SALES.SUBSCRIPTION_PLANS(PLAN_ID)
)COMMENT='One row per recurring subscription billing event. Charges on game-specific plans roll into per-game MONTHLY_REVENUE; platform-wide plan charges roll only into VW_PLATFORM_REVENUE_SUMMARY.'
;

-- GAME_SALES.TITLES
create or replace TABLE ONTOLOGY_DEMO.GAME_SALES.TITLES (
	TITLE_ID NUMBER(38,0) NOT NULL,
	TITLE_NAME VARCHAR(16777216),
	STUDIO VARCHAR(16777216) COMMENT 'Development studio',
	PUBLISHER_LABEL VARCHAR(16777216) COMMENT 'Publishing label',
	CATALOG_GAME_ID NUMBER(38,0) COMMENT 'Game id in the catalog system, when known',
	RELEASE_DATE VARCHAR(8),
	primary key (TITLE_ID)
)COMMENT='Sales system copy of the games it sells: ID, official title and release date only. Game descriptive data (developer, POV, narrative, franchise) lives in GAME_CATALOG. Loaded from data/GAME_SALES (no sync process).'
;

-- GAME_SALES.TITLE_CODE_XREF
create or replace TABLE ONTOLOGY_DEMO.GAME_SALES.TITLE_CODE_XREF (
	TITLE_CODE VARCHAR(16777216) NOT NULL COMMENT 'PlayStation Store title code',
	TITLE_ID NUMBER(38,0) NOT NULL,
	PLATFORM_CODE VARCHAR(16777216) NOT NULL,
	CATALOG_GAME_ID NUMBER(38,0),
	primary key (TITLE_CODE)
)COMMENT='PlayStation Store title code list'
;

-- (c) Load each table that has a data file
COPY INTO ONTOLOGY_DEMO.GAME_CATALOG.ACCESSIBILITY_FEATURES FROM @ONTOLOGY_DEMO.PUBLIC.DATA_STAGE/GAME_CATALOG/
