-- (d) Functions, procedures, views and dynamic tables
-- GAME_CATALOG/functions/UDF_JACCARD_SIMILARITY.sql
CREATE OR REPLACE FUNCTION ONTOLOGY_DEMO.GAME_CATALOG.UDF_JACCARD_SIMILARITY("SET_A" ARRAY, "SET_B" ARRAY)
RETURNS FLOAT
LANGUAGE SQL
AS '
    CASE
        WHEN (SET_A IS NULL OR ARRAY_SIZE(SET_A) = 0) AND (SET_B IS NULL OR ARRAY_SIZE(SET_B) = 0) THEN NULL
        WHEN SET_A IS NULL OR ARRAY_SIZE(SET_A) = 0 THEN 0.0
        WHEN SET_B IS NULL OR ARRAY_SIZE(SET_B) = 0 THEN 0.0
        ELSE ARRAY_SIZE(ARRAY_INTERSECTION(SET_A, SET_B))::FLOAT
             / ARRAY_SIZE(ARRAY_DISTINCT(ARRAY_CAT(SET_A, SET_B)))::FLOAT
    END
';

-- GAME_CATALOG/procedures/SP_CLASSIFICATION_GAP.sql
CREATE OR REPLACE PROCEDURE ONTOLOGY_DEMO.GAME_CATALOG.SP_CLASSIFICATION_GAP("P_GAME_ID" NUMBER(38,0), "P_GENRE" VARCHAR)
RETURNS TABLE ("CONDITION" VARCHAR, "STATUS" VARCHAR, "DETAILS" VARCHAR)
LANGUAGE SQL
EXECUTE AS OWNER
AS 'DECLARE
    res RESULTSET;
BEGIN
    res := (
        SELECT f.VALUE::STRING AS CONDITION, ''MET'' AS STATUS, '''' AS DETAILS
        FROM GAME_GENRE_CLASSIFICATION c,
             LATERAL FLATTEN(input => c.MATCHED_CONDITIONS) f
        WHERE c.GAME_ID = :P_GAME_ID AND c.GENRE = :P_GENRE
        
        UNION ALL
        
        SELECT f.VALUE::STRING, ''MISSING'', ''''
        FROM GAME_GENRE_CLASSIFICATION c,
             LATERAL FLATTEN(input => c.MISSING_CONDITIONS) f
        WHERE c.GAME_ID = :P_GAME_ID AND c.GENRE = :P_GENRE
        
        UNION ALL
        
        SELECT f.VALUE::STRING, ''UNKNOWN'', ''''
        FROM GAME_GENRE_CLASSIFICATION c,
             LATERAL FLATTEN(input => c.UNKNOWN_CONDITIONS) f
        WHERE c.GAME_ID = :P_GAME_ID AND c.GENRE = :P_GENRE
    );
    RETURN TABLE(res);
END';

-- GAME_CATALOG/views/VW_GAME_PROFILE.sql
create or replace view ONTOLOGY_DEMO.GAME_CATALOG.VW_GAME_PROFILE(
	GAME_ID,
	GAME_NAME,
	POV,
	NARRATIVE,
	GAMEPLAY_TYPES,
	MECHANICS,
	CONTEXTS,
	MAX_PLAYER_COUNT,
	HAS_ONLINE_MODE
) as
SELECT
    g.GAME_ID,
    g.GAME_NAME,
    g.POV,
    ns.STRUCTURE_NAME AS NARRATIVE,
    ARRAY_AGG(DISTINCT gt.GAMEPLAY_TYPE_NAME) AS GAMEPLAY_TYPES,
    ARRAY_AGG(DISTINCT m.MECHANIC_NAME) AS MECHANICS,
    ARRAY_AGG(DISTINCT c.CONTEXT_NAME) AS CONTEXTS,
    MAX(gm.MAX_PLAYERS) AS MAX_PLAYER_COUNT,
    BOOLOR_AGG(gm.ONLINE_REQUIRED) AS HAS_ONLINE_MODE
FROM ONTOLOGY_DEMO.GAME_CATALOG.GAMES g
LEFT JOIN ONTOLOGY_DEMO.GAME_CATALOG.NARRATIVE_STRUCTURES ns ON g.NARRATIVE_STRUCTURE_ID = ns.STRUCTURE_ID
LEFT JOIN ONTOLOGY_DEMO.GAME_CATALOG.GAME_GAMEPLAY gg ON g.GAME_ID = gg.GAME_ID
LEFT JOIN ONTOLOGY_DEMO.GAME_CATALOG.GAMEPLAY_TYPES gt ON gg.GAMEPLAY_TYPE_ID = gt.GAMEPLAY_TYPE_ID
LEFT JOIN ONTOLOGY_DEMO.GAME_CATALOG.GAME_MECHANICS gmc ON g.GAME_ID = gmc.GAME_ID
LEFT JOIN ONTOLOGY_DEMO.GAME_CATALOG.MECHANICS m ON gmc.MECHANIC_ID = m.MECHANIC_ID
LEFT JOIN ONTOLOGY_DEMO.GAME_CATALOG.GAME_CONTEXTS gc ON g.GAME_ID = gc.GAME_ID
LEFT JOIN ONTOLOGY_DEMO.GAME_CATALOG.CONTEXTS c ON gc.CONTEXT_ID = c.CONTEXT_ID
LEFT JOIN ONTOLOGY_DEMO.GAME_CATALOG.GAME_MODES gm ON g.GAME_ID = gm.GAME_ID
GROUP BY g.GAME_ID, g.GAME_NAME, g.POV, ns.STRUCTURE_NAME;

-- GAME_CATALOG/procedures/SP_CLASSIFY_GAMES.sql
CREATE OR REPLACE PROCEDURE ONTOLOGY_DEMO.GAME_CATALOG.SP_CLASSIFY_GAMES()
RETURNS VARCHAR
LANGUAGE PYTHON
RUNTIME_VERSION = '3.11'
PACKAGES = ('snowflake-snowpark-python')
HANDLER = 'run'
EXECUTE AS OWNER
AS '
import json
import re

def run(session):
    def parse_array(val):
        if val is None:
            return set()
        if isinstance(val, str):
            try:
                parsed = json.loads(val)
                return set(v for v in parsed if v is not None)
            except:
                return set()
        if isinstance(val, list):
            return set(v for v in val if v is not None)
        return set()

    rules_df = session.sql("SELECT GENRE, RULE_DEFINITION FROM ONTOLOGY_DEMO.GAME_CATALOG.GENRE_RULES WHERE RULE_DEFINITION IS NOT NULL").collect()
    rules = [(r[''GENRE''], r[''RULE_DEFINITION'']) for r in rules_df]

    cat_df = session.sql("SELECT CATEGORY_NAME, PREDICATE_TYPE, CONCRETE_VALUE FROM ONTOLOGY_DEMO.GAME_CATALOG.GENRE_CATEGORY_MAP").collect()
    categories = {}
    for row in cat_df:
        key = (row[''PREDICATE_TYPE''], row[''CATEGORY_NAME''])
        categories.setdefault(key, set()).add(row[''CONCRETE_VALUE''])

    profiles_df = session.sql("""
        SELECT GAME_ID, GAME_NAME, POV, NARRATIVE,
                GAMEPLAY_TYPES, MECHANICS, CONTEXTS,
                MAX_PLAYER_COUNT, HAS_ONLINE_MODE
        FROM ONTOLOGY_DEMO.GAME_CATALOG.VW_GAME_PROFILE
    """).collect()

    mon_df = session.sql("""
        SELECT g.GAME_ID, ARRAY_AGG(DISTINCT mt.MONETIZATION_NAME) AS MONETIZATION_TYPES
        FROM ONTOLOGY_DEMO.GAME_CATALOG.GAMES g
        LEFT JOIN ONTOLOGY_DEMO.GAME_CATALOG.GAME_MONETIZATION gm ON g.GAME_ID = gm.GAME_ID
        LEFT JOIN ONTOLOGY_DEMO.GAME_CATALOG.MONETIZATION_TYPES mt ON gm.MONETIZATION_ID = mt.MONETIZATION_ID
        GROUP BY g.GAME_ID
    """).collect()
    monetization_map = {}
    for row in mon_df:
        monetization_map[row[''GAME_ID'']] = parse_array(row[''MONETIZATION_TYPES''])

    games = []
    for row in profiles_df:
        games.append({
            ''game_id'': row[''GAME_ID''],
            ''game_name'': row[''GAME_NAME''],
            ''pov'': row[''POV''] if row[''POV''] else '''',
            ''narrative'': row[''NARRATIVE''] if row[''NARRATIVE''] else '''',
            ''gameplay'': parse_array(row[''GAMEPLAY_TYPES'']),
            ''mechanic'': parse_array(row[''MECHANICS'']),
            ''context'': parse_array(row[''CONTEXTS'']),
            ''max_players'': row[''MAX_PLAYER_COUNT''],
            ''online'': row[''HAS_ONLINE_MODE''],
            ''monetization'': monetization_map.get(row[''GAME_ID''], set())
        })

    UNEVALUABLE_PREDICATES = {''hasDifficulty'', ''hasUpdate''}

    def parse_conditions(rule_def):
        if not rule_def or not rule_def.strip():
            return []
        rule_def = rule_def.strip()
        if rule_def.startswith(''INTERSECTION('') and rule_def.endswith('')''):
            inner = rule_def[13:-1]
            conditions = []
            depth = 0
            current = ''''
            for ch in inner:
                if ch in (''('', ''{''):
                    depth += 1
                    current += ch
                elif ch in ('')'', ''}''):
                    depth -= 1
                    current += ch
                elif ch == '','' and depth == 0:
                    conditions.append(current.strip())
                    current = ''''
                else:
                    current += ch
            if current.strip():
                conditions.append(current.strip())
            return conditions
        else:
            return [rule_def]

    def evaluate_condition(cond, game, categories):
        cond = cond.strip()
        if cond.startswith(''NOT('') and cond.endswith('')''):
            inner_cond = cond[4:-1]
            if inner_cond == ''requiresOnline'':
                if game[''online''] is None:
                    return (''UNKNOWN'', ''requiresOnline: no mode data'')
                return (''MET'', ''NOT online'') if not game[''online''] else (''MISSING'', ''game requires online'')
            result, detail = evaluate_condition(inner_cond, game, categories)
            if result == ''MET'':
                return (''MISSING'', f''NOT failed: {detail}'')
            elif result == ''MISSING'':
                return (''MET'', f''NOT passed: {detail}'')
            else:
                return (''UNKNOWN'', f''NOT unknown: {detail}'')

        m = re.match(r''(has\\w+|requiresOnline)\\s+(SOME|VALUE|MIN|MAX)\\s+(.*)'', cond)
        if not m:
            return (''UNKNOWN'', f''unparseable: {cond}'')

        predicate, operator, operand = m.group(1), m.group(2), m.group(3).strip()

        if predicate in UNEVALUABLE_PREDICATES:
            return (''UNKNOWN'', f''{predicate}: no data available'')

        prop_map = {
            ''hasGameplay'': (''gameplay'', ''array''),
            ''hasMechanic'': (''mechanic'', ''array''),
            ''hasContext'': (''context'', ''array''),
            ''hasPOV'': (''pov'', ''scalar''),
            ''hasNarrative'': (''narrative'', ''scalar''),
            ''hasPlayerCount'': (''max_players'', ''numeric''),
            ''requiresOnline'': (''online'', ''boolean''),
            ''hasMonetization'': (''monetization'', ''array''),
        }

        if predicate not in prop_map:
            return (''UNKNOWN'', f''unknown predicate: {predicate}'')

        prop_key, prop_type = prop_map[predicate]
        game_val = game[prop_key]

        if operator == ''VALUE'':
            if prop_type == ''array'':
                if not game_val:
                    return (''UNKNOWN'', f''{predicate}: no data'')
                if operand in game_val:
                    return (''MET'', f''{predicate}={operand}'')
                return (''MISSING'', f''{predicate} missing {operand}'')
            elif prop_type == ''scalar'':
                if game_val == operand:
                    return (''MET'', f''{predicate}={operand}'')
                return (''MISSING'', f''{predicate}={game_val} needs {operand}'')
            elif prop_type == ''boolean'':
                expected = operand.lower() == ''true''
                if game_val is None:
                    return (''UNKNOWN'', f''{predicate}: no data'')
                if game_val == expected:
                    return (''MET'', f''{predicate}={operand}'')
                return (''MISSING'', f''{predicate}={game_val} needs {operand}'')

        elif operator == ''SOME'':
            if operand.startswith(''{'') and operand.endswith(''}''):
                values = set(v.strip() for v in operand[1:-1].split('',''))
                if prop_type == ''array'':
                    if not game_val:
                        return (''UNKNOWN'', f''{predicate}: no data'')
                    overlap = game_val & values
                    if overlap:
                        return (''MET'', f''{predicate} has {overlap}'')
                    return (''MISSING'', f''{predicate} needs one of {values}'')
                elif prop_type == ''scalar'':
                    if game_val in values:
                        return (''MET'', f''{predicate}={game_val}'')
                    return (''MISSING'', f''{predicate}={game_val} not in {values}'')
            else:
                cat_key = (prop_key, operand)
                concrete = categories.get(cat_key, set())
                if not concrete:
                    return (''UNKNOWN'', f''no category mapping: {prop_key}/{operand}'')
                if prop_type == ''array'':
                    if not game_val:
                        return (''UNKNOWN'', f''{predicate}: no data'')
                    overlap = game_val & concrete
                    if overlap:
                        return (''MET'', f''{predicate} SOME {operand}: {overlap}'')
                    return (''MISSING'', f''{predicate} SOME {operand}: none of {concrete}'')
                elif prop_type == ''scalar'':
                    if game_val in concrete:
                        return (''MET'', f''{predicate} SOME {operand}: {game_val}'')
                    return (''MISSING'', f''{predicate} SOME {operand}: {game_val} not in {concrete}'')

        elif operator == ''MIN'':
            threshold = int(operand)
            if game_val is None:
                return (''UNKNOWN'', f''{predicate}: no player count'')
            if game_val >= threshold:
                return (''MET'', f''players={game_val}>={threshold}'')
            return (''MISSING'', f''players={game_val}<{threshold}'')

        elif operator == ''MAX'':
            threshold = int(operand)
            if game_val is None:
                return (''UNKNOWN'', f''{predicate}: no player count'')
            if game_val <= threshold:
                return (''MET'', f''players={game_val}<={threshold}'')
            return (''MISSING'', f''players={game_val}>{threshold}'')

        return (''UNKNOWN'', f''unhandled: {cond}'')

    results = []
    for game in games:
        for genre, rule_def in rules:
            conditions = parse_conditions(rule_def)
            if not conditions:
                continue

            met, missing, unknown = [], [], []
            for cond in conditions:
                status, detail = evaluate_condition(cond, game, categories)
                if status == ''MET'':
                    met.append(detail)
                elif status == ''MISSING'':
                    missing.append(detail)
                else:
                    unknown.append(detail)

            total = len(conditions)
            met_count = len(met)
            score = met_count / max(total, 1)

            if unknown and not missing and met_count + len(unknown) == total:
                match_status = ''UNEVALUABLE'' if met_count == 0 else ''PARTIAL''
            elif met_count == total:
                match_status = ''FULL''
            elif met_count > 0:
                match_status = ''PARTIAL''
            else:
                match_status = ''NONE''

            results.append((
                game[''game_id''], game[''game_name''], genre, match_status,
                round(score, 4), total, met_count,
                json.dumps(met), json.dumps(missing), json.dumps(unknown)
            ))

    session.sql("TRUNCATE TABLE ONTOLOGY_DEMO.GAME_CATALOG.GAME_GENRE_CLASSIFICATION").collect()

    batch_size = 100
    for i in range(0, len(results), batch_size):
        batch = results[i:i+batch_size]
        selects = []
        for r in batch:
            gid, gn, ge, ms, sc, tot, mc, ma, mi, uk = r
            gn = gn.replace("''", "''''") if gn else ''''
            ge = ge.replace("''", "''''")
            ma = ma.replace("''", "''''")
            mi = mi.replace("''", "''''")
            uk = uk.replace("''", "''''")
            selects.append(
                f"SELECT {gid}, ''{gn}'', ''{ge}'', ''{ms}'', "
                f"{sc}, {tot}, {mc}, "
                f"PARSE_JSON(''{ma}''), PARSE_JSON(''{mi}''), PARSE_JSON(''{uk}'')"
            )
        sql = f"""INSERT INTO ONTOLOGY_DEMO.GAME_CATALOG.GAME_GENRE_CLASSIFICATION
            (GAME_ID, GAME_NAME, GENRE, MATCH_STATUS, MATCH_SCORE, TOTAL_CONDITIONS, MET_CONDITIONS, MATCHED_CONDITIONS, MISSING_CONDITIONS, UNKNOWN_CONDITIONS)
            {'' UNION ALL ''.join(selects)}"""
        session.sql(sql).collect()

    return f''Classified {len(games)} games against {len(rules)} rules. {len(results)} evaluations.''
';

-- GAME_CATALOG/views/VW_GAME_OVERLAP_MATRIX.sql
create or replace view ONTOLOGY_DEMO.GAME_CATALOG.VW_GAME_OVERLAP_MATRIX(
	GAME_A_ID,
	GAME_A_NAME,
	GAME_B_ID,
	GAME_B_NAME,
	GENRE_OVERLAP,
	PLATFORM_OVERLAP,
	MECHANIC_OVERLAP,
	GAMEPLAY_OVERLAP,
	CONTEXT_OVERLAP,
	POV_MATCH,
	NARRATIVE_MATCH
) COMMENT='The table contains records of game overlap matrices, specifically comparisons between different games. Each record represents a pair of games and includes details about their shared genres, platforms, mechanics, gameplay, and other characteristics.'
 as
WITH game_genres AS (
    SELECT GAME_ID, ARRAY_AGG(DISTINCT GENRE) AS GENRES
    FROM ONTOLOGY_DEMO.GAME_CATALOG.GAME_GENRE_CLASSIFICATION
    WHERE MATCH_STATUS = 'FULL'
    GROUP BY GAME_ID
), game_plats AS (
    SELECT gp.GAME_ID, ARRAY_AGG(DISTINCT p.PLATFORM_NAME) AS PLATFORMS
    FROM ONTOLOGY_DEMO.GAME_CATALOG.GAME_PLATFORMS gp
    JOIN ONTOLOGY_DEMO.GAME_CATALOG.PLATFORMS p ON gp.PLATFORM_ID = p.PLATFORM_ID
    GROUP BY gp.GAME_ID
), profiles AS (
    SELECT GAME_ID, GAME_NAME, POV, NARRATIVE,
           GAMEPLAY_TYPES AS GAMEPLAY_ARR,
           MECHANICS AS MECHANIC_ARR,
           CONTEXTS AS CONTEXT_ARR
    FROM ONTOLOGY_DEMO.GAME_CATALOG.VW_GAME_PROFILE
)
SELECT
    a.GAME_ID AS GAME_A_ID, a.GAME_NAME AS GAME_A_NAME,
    b.GAME_ID AS GAME_B_ID, b.GAME_NAME AS GAME_B_NAME,
    ONTOLOGY_DEMO.GAME_CATALOG.UDF_JACCARD_SIMILARITY(ga.GENRES, gb.GENRES) AS GENRE_OVERLAP,
    ONTOLOGY_DEMO.GAME_CATALOG.UDF_JACCARD_SIMILARITY(pa.PLATFORMS, pb.PLATFORMS) AS PLATFORM_OVERLAP,
    ONTOLOGY_DEMO.GAME_CATALOG.UDF_JACCARD_SIMILARITY(a.MECHANIC_ARR, b.MECHANIC_ARR) AS MECHANIC_OVERLAP,
    ONTOLOGY_DEMO.GAME_CATALOG.UDF_JACCARD_SIMILARITY(a.GAMEPLAY_ARR, b.GAMEPLAY_ARR) AS GAMEPLAY_OVERLAP,
    ONTOLOGY_DEMO.GAME_CATALOG.UDF_JACCARD_SIMILARITY(a.CONTEXT_ARR, b.CONTEXT_ARR) AS CONTEXT_OVERLAP,
    CASE WHEN a.POV = b.POV AND a.POV IS NOT NULL THEN 1.0 ELSE 0.0 END AS POV_MATCH,
    CASE WHEN a.NARRATIVE = b.NARRATIVE AND a.NARRATIVE IS NOT NULL THEN 1.0 ELSE 0.0 END AS NARRATIVE_MATCH
FROM profiles a
JOIN profiles b ON a.GAME_ID < b.GAME_ID
LEFT JOIN game_genres ga ON a.GAME_ID = ga.GAME_ID
LEFT JOIN game_genres gb ON b.GAME_ID = gb.GAME_ID
LEFT JOIN game_plats pa ON a.GAME_ID = pa.GAME_ID
LEFT JOIN game_plats pb ON b.GAME_ID = pb.GAME_ID;

-- GAME_CATALOG/dynamic_tables/GAME_SIMILARITY_SCORES.sql
create or replace dynamic table ONTOLOGY_DEMO.GAME_CATALOG.GAME_SIMILARITY_SCORES(
	GAME_A_ID,
	GAME_A_NAME,
	GAME_B_ID,
	GAME_B_NAME,
	GENRE_OVERLAP,
	PLATFORM_OVERLAP,
	MECHANIC_OVERLAP,
	GAMEPLAY_OVERLAP,
	CONTEXT_OVERLAP,
	POV_MATCH,
	NARRATIVE_MATCH,
	WEIGHTED_OVERLAP,
	OVERLAP_TIER
) target_lag = '1 hour' refresh_mode = AUTO initialize = ON_CREATE warehouse = COMPUTE_WH
 as
WITH weights AS (
    SELECT
        MAX(CASE WHEN DIMENSION_NAME = 'GENRE' THEN WEIGHT END) AS W_GENRE,
        MAX(CASE WHEN DIMENSION_NAME = 'PLATFORM' THEN WEIGHT END) AS W_PLATFORM,
        MAX(CASE WHEN DIMENSION_NAME = 'MECHANIC' THEN WEIGHT END) AS W_MECHANIC,
        MAX(CASE WHEN DIMENSION_NAME = 'GAMEPLAY' THEN WEIGHT END) AS W_GAMEPLAY,
        MAX(CASE WHEN DIMENSION_NAME = 'CONTEXT' THEN WEIGHT END) AS W_CONTEXT,
        MAX(CASE WHEN DIMENSION_NAME = 'POV' THEN WEIGHT END) AS W_POV,
        MAX(CASE WHEN DIMENSION_NAME = 'NARRATIVE' THEN WEIGHT END) AS W_NARRATIVE
    FROM ONTOLOGY_DEMO.GAME_CATALOG.SIMILARITY_WEIGHTS
), scored AS (
    SELECT
        m.GAME_A_ID, m.GAME_A_NAME, m.GAME_B_ID, m.GAME_B_NAME,
        m.GENRE_OVERLAP, m.PLATFORM_OVERLAP, m.MECHANIC_OVERLAP,
        m.GAMEPLAY_OVERLAP, m.CONTEXT_OVERLAP, m.POV_MATCH, m.NARRATIVE_MATCH,
        (COALESCE(m.GENRE_OVERLAP, 0) * w.W_GENRE
       + COALESCE(m.PLATFORM_OVERLAP, 0) * w.W_PLATFORM
       + COALESCE(m.MECHANIC_OVERLAP, 0) * w.W_MECHANIC
       + COALESCE(m.GAMEPLAY_OVERLAP, 0) * w.W_GAMEPLAY
       + COALESCE(m.CONTEXT_OVERLAP, 0) * w.W_CONTEXT
       + m.POV_MATCH * w.W_POV
       + m.NARRATIVE_MATCH * w.W_NARRATIVE) AS WEIGHTED_OVERLAP
    FROM ONTOLOGY_DEMO.GAME_CATALOG.VW_GAME_OVERLAP_MATRIX m
    CROSS JOIN weights w
)
SELECT
    GAME_A_ID, GAME_A_NAME, GAME_B_ID, GAME_B_NAME,
    GENRE_OVERLAP, PLATFORM_OVERLAP, MECHANIC_OVERLAP,
    GAMEPLAY_OVERLAP, CONTEXT_OVERLAP, POV_MATCH, NARRATIVE_MATCH,
    ROUND(WEIGHTED_OVERLAP, 4) AS WEIGHTED_OVERLAP,
    CASE
        WHEN WEIGHTED_OVERLAP >= 0.6 THEN 'HIGH'
        WHEN WEIGHTED_OVERLAP >= 0.3 THEN 'MEDIUM'
        ELSE 'LOW'
    END AS OVERLAP_TIER
FROM scored;

-- GAME_CATALOG/procedures/SP_FIND_CANNIBALIZATION.sql
CREATE OR REPLACE PROCEDURE ONTOLOGY_DEMO.GAME_CATALOG.SP_FIND_CANNIBALIZATION("THRESHOLD" FLOAT DEFAULT 0.4)
RETURNS TABLE ("GAME_A" VARCHAR, "GAME_B" VARCHAR, "PUBLISHER" VARCHAR, "WEIGHTED_OVERLAP" FLOAT, "GENRE_OVERLAP" FLOAT, "PLATFORM_OVERLAP" FLOAT, "OVERLAP_TIER" VARCHAR)
LANGUAGE SQL
EXECUTE AS OWNER
AS 'BEGIN
    LET res RESULTSET := (
        SELECT
            s.GAME_A_NAME AS GAME_A,
            s.GAME_B_NAME AS GAME_B,
            ga.PUBLISHER_NAME AS PUBLISHER,
            s.WEIGHTED_OVERLAP,
            s.GENRE_OVERLAP,
            s.PLATFORM_OVERLAP,
            s.OVERLAP_TIER
        FROM ONTOLOGY_DEMO.GAME_CATALOG.GAME_SIMILARITY_SCORES s
        JOIN ONTOLOGY_DEMO.GAME_CATALOG.GAMES ga ON s.GAME_A_ID = ga.GAME_ID
        JOIN ONTOLOGY_DEMO.GAME_CATALOG.GAMES gb ON s.GAME_B_ID = gb.GAME_ID
        WHERE ga.PUBLISHER_NAME = gb.PUBLISHER_NAME
          AND s.WEIGHTED_OVERLAP >= :THRESHOLD
        ORDER BY s.WEIGHTED_OVERLAP DESC
    );
    RETURN TABLE(res);
END';

-- GAME_CATALOG/views/DISJOINT_GENRE_PAIRS.sql
create or replace view ONTOLOGY_DEMO.GAME_CATALOG.DISJOINT_GENRE_PAIRS(
	GENRE_A,
	GENRE_B,
	REASON
) COMMENT='The table contains records of relationships between different genres. Each record represents a pair of genres and includes the reason for their connection.'
 as
SELECT GENRE AS GENRE_A, TRIM(VALUE::STRING) AS GENRE_B,
       'Declared disjoint in GENRE_RULES' AS REASON
FROM ONTOLOGY_DEMO.GAME_CATALOG.GENRE_RULES, LATERAL FLATTEN(INPUT => SPLIT(DISJOINT_WITH, ','))
WHERE DISJOINT_WITH IS NOT NULL AND DISJOINT_WITH != '' AND DISJOINT_WITH != 'None';

-- GAME_CATALOG/views/VW_ACCESSIBILITY_GAPS.sql
create or replace view ONTOLOGY_DEMO.GAME_CATALOG.VW_ACCESSIBILITY_GAPS(
	GAME_ID,
	GAME_NAME,
	FEATURE_ID,
	FEATURE_NAME,
	FEATURE_CATEGORY,
	IS_SUPPORTED
) as
SELECT
    g.GAME_ID, g.GAME_NAME,
    af.FEATURE_ID, af.FEATURE_NAME, af.FEATURE_CATEGORY,
    CASE WHEN ga.GAME_ID IS NOT NULL THEN TRUE ELSE FALSE END AS IS_SUPPORTED
FROM ONTOLOGY_DEMO.GAME_CATALOG.GAMES g
CROSS JOIN ONTOLOGY_DEMO.GAME_CATALOG.ACCESSIBILITY_FEATURES af
LEFT JOIN ONTOLOGY_DEMO.GAME_CATALOG.GAME_ACCESSIBILITY ga
  ON g.GAME_ID = ga.GAME_ID AND af.FEATURE_ID = ga.FEATURE_ID;

-- GAME_CATALOG/views/VW_CANNIBALIZATION_CANDIDATES.sql
create or replace view ONTOLOGY_DEMO.GAME_CATALOG.VW_CANNIBALIZATION_CANDIDATES(
	GAME_A_NAME,
	GAME_B_NAME,
	PUBLISHER_NAME,
	WEIGHTED_OVERLAP,
	GENRE_OVERLAP,
	PLATFORM_OVERLAP,
	MECHANIC_OVERLAP,
	GAMEPLAY_OVERLAP,
	OVERLAP_TIER
) as
SELECT
    s.GAME_A_NAME, s.GAME_B_NAME,
    ga.PUBLISHER_NAME,
    s.WEIGHTED_OVERLAP, s.GENRE_OVERLAP, s.PLATFORM_OVERLAP,
    s.MECHANIC_OVERLAP, s.GAMEPLAY_OVERLAP,
    s.OVERLAP_TIER
FROM ONTOLOGY_DEMO.GAME_CATALOG.GAME_SIMILARITY_SCORES s
JOIN ONTOLOGY_DEMO.GAME_CATALOG.GAMES ga ON s.GAME_A_ID = ga.GAME_ID
JOIN ONTOLOGY_DEMO.GAME_CATALOG.GAMES gb ON s.GAME_B_ID = gb.GAME_ID
WHERE ga.PUBLISHER_NAME = gb.PUBLISHER_NAME
  AND s.WEIGHTED_OVERLAP >= 0.3;

-- GAME_CATALOG/views/VW_GENRE_HIERARCHY.sql
create or replace view ONTOLOGY_DEMO.GAME_CATALOG.VW_GENRE_HIERARCHY(
	GENRE,
	PARENT_GENRE,
	DEPTH,
	PATH,
	IS_LEAF,
	HAS_RULE
) COMMENT='The table contains a hierarchical structure of genres, with each record representing a specific genre and its relationships to other genres. Each record includes details about the genre''s position in the hierarchy, including its parent genre and depth level, as well as whether it is a leaf node and if it has any associated rules.'
 as
WITH RECURSIVE tree AS (
    SELECT GENRE, PARENT_GENRE, 0 AS DEPTH, GENRE::VARCHAR AS PATH, RULE_DEFINITION
    FROM ONTOLOGY_DEMO.GAME_CATALOG.GENRE_RULES
    WHERE PARENT_GENRE IS NULL
    UNION ALL
    SELECT c.GENRE, c.PARENT_GENRE, t.DEPTH + 1, t.PATH || ' > ' || c.GENRE, c.RULE_DEFINITION
    FROM ONTOLOGY_DEMO.GAME_CATALOG.GENRE_RULES c
    JOIN tree t ON c.PARENT_GENRE = t.GENRE
)
SELECT t.GENRE, t.PARENT_GENRE, t.DEPTH, t.PATH,
       NOT EXISTS (SELECT 1 FROM ONTOLOGY_DEMO.GAME_CATALOG.GENRE_RULES c WHERE c.PARENT_GENRE = t.GENRE) AS IS_LEAF,
       t.RULE_DEFINITION IS NOT NULL AS HAS_RULE
FROM tree t;

-- GAME_CATALOG/views/VW_GAME_GENRE_ROLLUP.sql
create or replace view ONTOLOGY_DEMO.GAME_CATALOG.VW_GAME_GENRE_ROLLUP(
	GAME_ID,
	ROLLUP_GENRE,
	ROLLUP_DEPTH
) COMMENT='One row per game per genre it belongs to: each FULL-matched genre plus all its ancestors in the PARENT_GENRE tree. Distinct per (GAME_ID, ROLLUP_GENRE).'
 as
WITH RECURSIVE anc AS (
    SELECT GENRE, GENRE AS ANCESTOR_GENRE
    FROM ONTOLOGY_DEMO.GAME_CATALOG.GENRE_RULES
    UNION ALL
    SELECT a.GENRE, r.PARENT_GENRE
    FROM anc a
    JOIN ONTOLOGY_DEMO.GAME_CATALOG.GENRE_RULES r ON r.GENRE = a.ANCESTOR_GENRE
    WHERE r.PARENT_GENRE IS NOT NULL
)
SELECT DISTINCT c.GAME_ID, a.ANCESTOR_GENRE AS ROLLUP_GENRE, h.DEPTH AS ROLLUP_DEPTH
FROM ONTOLOGY_DEMO.GAME_CATALOG.GAME_GENRE_CLASSIFICATION c
JOIN anc a ON a.GENRE = c.GENRE
JOIN ONTOLOGY_DEMO.GAME_CATALOG.VW_GENRE_HIERARCHY h ON h.GENRE = a.ANCESTOR_GENRE
WHERE c.MATCH_STATUS = 'FULL'
  AND h.PARENT_GENRE IS NOT NULL;

-- GAME_CATALOG/dynamic_tables/GENRE_WHITESPACE_ANALYSIS.sql
create or replace dynamic table ONTOLOGY_DEMO.GAME_CATALOG.GENRE_WHITESPACE_ANALYSIS(
	GENRE_A,
	GENRE_B,
	GAME_COUNT,
	MARKET_STATUS
) target_lag = '1 hour' refresh_mode = AUTO initialize = ON_CREATE warehouse = COMPUTE_WH
 as
WITH leaf_genres AS (
    SELECT r.GENRE FROM ONTOLOGY_DEMO.GAME_CATALOG.GENRE_RULES r
    WHERE r.RULE_DEFINITION IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM ONTOLOGY_DEMO.GAME_CATALOG.GENRE_RULES c
                      WHERE c.PARENT_GENRE = r.GENRE)
), disjoint_pairs AS (
    SELECT GENRE AS GENRE_A, TRIM(VALUE::STRING) AS GENRE_B
    FROM ONTOLOGY_DEMO.GAME_CATALOG.GENRE_RULES,
    LATERAL FLATTEN(INPUT => SPLIT(DISJOINT_WITH, ','))
    WHERE DISJOINT_WITH IS NOT NULL AND DISJOINT_WITH != '' AND DISJOINT_WITH != 'None'
), all_pairs AS (
    SELECT a.GENRE AS GENRE_A, b.GENRE AS GENRE_B
    FROM leaf_genres a JOIN leaf_genres b ON a.GENRE < b.GENRE
), valid_pairs AS (
    SELECT ap.* FROM all_pairs ap
    WHERE NOT EXISTS (
        SELECT 1 FROM disjoint_pairs dp
        WHERE (dp.GENRE_A = ap.GENRE_A AND dp.GENRE_B = ap.GENRE_B)
           OR (dp.GENRE_A = ap.GENRE_B AND dp.GENRE_B = ap.GENRE_A)
    )
), game_genre_pairs AS (
    SELECT a.GAME_ID, a.GENRE AS GENRE_A, b.GENRE AS GENRE_B
    FROM ONTOLOGY_DEMO.GAME_CATALOG.GAME_GENRE_CLASSIFICATION a
    JOIN ONTOLOGY_DEMO.GAME_CATALOG.GAME_GENRE_CLASSIFICATION b
      ON a.GAME_ID = b.GAME_ID AND a.GENRE < b.GENRE
    WHERE a.MATCH_STATUS = 'FULL' AND b.MATCH_STATUS = 'FULL'
)
SELECT
    vp.GENRE_A, vp.GENRE_B,
    COUNT(DISTINCT ggp.GAME_ID) AS GAME_COUNT,
    CASE
        WHEN COUNT(DISTINCT ggp.GAME_ID) = 0 THEN 'WHITESPACE'
        WHEN COUNT(DISTINCT ggp.GAME_ID) <= 2 THEN 'UNDERSERVED'
        ELSE 'SERVED'
    END AS MARKET_STATUS
FROM valid_pairs vp
LEFT JOIN game_genre_pairs ggp ON vp.GENRE_A = ggp.GENRE_A AND vp.GENRE_B = ggp.GENRE_B
GROUP BY vp.GENRE_A, vp.GENRE_B;

-- GAME_SALES/views/MONTHLY_REVENUE.sql
create or replace view ONTOLOGY_DEMO.GAME_SALES.MONTHLY_REVENUE(
	TITLE_ID,
	REVENUE_MONTH,
	MONTHLY_INCOME,
	CUMULATIVE_INCOME,
	REVENUE_SOURCE
) COMMENT='Per-title monthly revenue by monetization type, derived from DIGITAL_PRODUCT_TRANSACTIONS and title-specific SUBSCRIPTION_CHARGES. REVENUE_SOURCE is the REVENUE_TYPES.MONETIZATION_TYPE. CUMULATIVE_INCOME is the running total per title through the month.'
 as
WITH by_category AS (
    SELECT dp.TITLE_ID, DATE_TRUNC('MONTH', dpt.TRANSACTION_TIMESTAMP)::DATE AS REVENUE_MONTH,
           rt.MONETIZATION_TYPE AS REVENUE_SOURCE, SUM(dpt.GROSS_REVENUE) AS MONTHLY_INCOME
    FROM ONTOLOGY_DEMO.GAME_SALES.DIGITAL_PRODUCT_TRANSACTIONS dpt
    JOIN ONTOLOGY_DEMO.GAME_SALES.DIGITAL_PRODUCTS dp ON dpt.DIGITAL_PRODUCT_ID = dp.DIGITAL_PRODUCT_ID
    JOIN ONTOLOGY_DEMO.GAME_SALES.REVENUE_TYPES rt ON dp.CATEGORY_ID = rt.CATEGORY_ID
    GROUP BY 1, 2, 3
    UNION ALL
    SELECT sp.GAME_ID, DATE_TRUNC('MONTH', sc.CHARGE_TIMESTAMP)::DATE, 'SUBSCRIPTION', SUM(sc.GROSS_REVENUE)
    FROM ONTOLOGY_DEMO.GAME_SALES.SUBSCRIPTION_CHARGES sc
    JOIN ONTOLOGY_DEMO.GAME_SALES.SUBSCRIPTION_PLANS sp ON sc.PLAN_ID = sp.PLAN_ID
    WHERE sp.GAME_ID IS NOT NULL
    GROUP BY 1, 2
), month_totals AS (
    SELECT TITLE_ID, REVENUE_MONTH, SUM(MONTHLY_INCOME) AS MONTH_TOTAL
    FROM by_category GROUP BY TITLE_ID, REVENUE_MONTH
), cumulative AS (
    SELECT TITLE_ID, REVENUE_MONTH,
           SUM(MONTH_TOTAL) OVER (PARTITION BY TITLE_ID ORDER BY REVENUE_MONTH) AS CUMULATIVE_INCOME
    FROM month_totals
)
SELECT b.TITLE_ID, b.REVENUE_MONTH, b.MONTHLY_INCOME, c.CUMULATIVE_INCOME, b.REVENUE_SOURCE
FROM by_category b JOIN cumulative c USING (TITLE_ID, REVENUE_MONTH);

-- GAME_SALES/dynamic_tables/GAME_REVENUE.sql
create or replace dynamic table ONTOLOGY_DEMO.GAME_SALES.GAME_REVENUE(
	TITLE_ID,
	INCOME
) target_lag = '1 hour' refresh_mode = AUTO initialize = ON_CREATE warehouse = COMPUTE_WH
 as
SELECT TITLE_ID, SUM(MONTHLY_INCOME) AS INCOME
FROM ONTOLOGY_DEMO.GAME_SALES.MONTHLY_REVENUE
GROUP BY TITLE_ID;

-- GAME_SALES/views/VW_PLATFORM_EXCLUSIVITY.sql
create or replace view ONTOLOGY_DEMO.GAME_SALES.VW_PLATFORM_EXCLUSIVITY(
	TITLE_ID,
	TITLE_NAME,
	INCOME,
	PLATFORM_ID,
	PLATFORM_NAME,
	IS_EXCLUSIVE,
	EXCLUSIVITY_TYPE,
	EXCLUSIVE_START,
	EXCLUSIVE_END,
	EXCLUSIVITY_NOTE,
	IS_CURRENTLY_EXCLUSIVE
) as
SELECT
    t.TITLE_ID, t.TITLE_NAME, gr.INCOME,
    p.PLATFORM_ID, p.PLATFORM_NAME,
    gp.IS_EXCLUSIVE,
    gp.EXCLUSIVITY_TYPE,
    gp.EXCLUSIVE_START,
    gp.EXCLUSIVE_END,
    gp.EXCLUSIVITY_NOTE,
    CASE
        WHEN gp.EXCLUSIVITY_TYPE = 'PERMANENT' THEN TRUE
        WHEN gp.EXCLUSIVITY_TYPE = 'TIMED' AND gp.EXCLUSIVE_END >= CURRENT_DATE() THEN TRUE
        ELSE FALSE
    END AS IS_CURRENTLY_EXCLUSIVE
FROM ONTOLOGY_DEMO.GAME_SALES.GAME_PLATFORMS gp
JOIN ONTOLOGY_DEMO.GAME_SALES.TITLES t ON gp.TITLE_ID = t.TITLE_ID
JOIN ONTOLOGY_DEMO.GAME_SALES.PLATFORMS p ON gp.PLATFORM_ID = p.PLATFORM_ID
LEFT JOIN ONTOLOGY_DEMO.GAME_SALES.GAME_REVENUE gr ON t.TITLE_ID = gr.TITLE_ID
WHERE gp.IS_EXCLUSIVE = 'Y';

-- GAME_SALES/views/VW_PLATFORM_REVENUE_SUMMARY.sql
create or replace view ONTOLOGY_DEMO.GAME_SALES.VW_PLATFORM_REVENUE_SUMMARY(
	REVENUE_MONTH,
	CATEGORY_GROUP,
	GROSS_REVENUE,
	PLATFORM_REVENUE
) COMMENT='Business-wide monthly revenue by CATEGORY_GROUP (HARDWARE, DIGITAL, SUBSCRIPTION), including non-game revenue. GROSS_REVENUE is what customers paid. PLATFORM_REVENUE is what the platform keeps: all hardware and subscription revenue, and only the commission share of digital sales (GROSS_REVENUE - NET_DEVELOPER_REVENUE).'
 as
SELECT DATE_TRUNC('MONTH', SALE_TIMESTAMP)::DATE, 'HARDWARE', SUM(GROSS_REVENUE), SUM(GROSS_REVENUE)
FROM ONTOLOGY_DEMO.GAME_SALES.HARDWARE_SALES_TRANSACTIONS
GROUP BY 1
UNION ALL
SELECT DATE_TRUNC('MONTH', TRANSACTION_TIMESTAMP)::DATE, 'DIGITAL', SUM(GROSS_REVENUE), SUM(GROSS_REVENUE - NET_DEVELOPER_REVENUE)
FROM ONTOLOGY_DEMO.GAME_SALES.DIGITAL_PRODUCT_TRANSACTIONS
GROUP BY 1
UNION ALL
SELECT DATE_TRUNC('MONTH', CHARGE_TIMESTAMP)::DATE, 'SUBSCRIPTION', SUM(GROSS_REVENUE), SUM(GROSS_REVENUE)
FROM ONTOLOGY_DEMO.GAME_SALES.SUBSCRIPTION_CHARGES
GROUP BY 1;

-- GAME_SALES/dynamic_tables/QUARTERLY_REVENUE.sql
create or replace dynamic table ONTOLOGY_DEMO.GAME_SALES.QUARTERLY_REVENUE(
	TITLE_ID,
	REVENUE_YEAR,
	REVENUE_QUARTER,
	QUARTERLY_INCOME,
	CUMULATIVE_INCOME
) target_lag = '1 hour' refresh_mode = AUTO initialize = ON_CREATE warehouse = COMPUTE_WH
 as
SELECT TITLE_ID,
       YEAR(REVENUE_MONTH) AS REVENUE_YEAR,
       QUARTER(REVENUE_MONTH) AS REVENUE_QUARTER,
       SUM(MONTHLY_INCOME) AS QUARTERLY_INCOME,
       MAX(CUMULATIVE_INCOME) AS CUMULATIVE_INCOME
FROM ONTOLOGY_DEMO.GAME_SALES.MONTHLY_REVENUE
GROUP BY TITLE_ID, YEAR(REVENUE_MONTH), QUARTER(REVENUE_MONTH);

